package main

import (
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.ReleaseMode)

	r := gin.New()
	// MaxMultipartMemory 只管内存阈值，超出部分落临时文件，不限制总量
	r.MaxMultipartMemory = 8 << 20
	// 真正限制总量：请求体超过 1KB 就读不出来了
	r.Use(func(c *gin.Context) {
		c.Request.Body = http.MaxBytesReader(c.Writer, c.Request.Body, 1<<10)
		c.Next()
	})
	r.POST("/echo", func(c *gin.Context) {
		data, err := io.ReadAll(c.Request.Body)
		if err != nil {
			// 超限时标准库返回 *http.MaxBytesError（Go 1.19 起）
			var maxErr *http.MaxBytesError
			if errors.As(err, &maxErr) {
				c.JSON(http.StatusRequestEntityTooLarge, gin.H{"error": "请求体超过 1KB 限制"})
				return
			}
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusOK, gin.H{"size": len(data)})
	})

	fmt.Printf("MaxMultipartMemory = %d 字节\n", r.MaxMultipartMemory)

	w := httptest.NewRecorder()
	body := strings.NewReader(strings.Repeat("x", 2048))
	req := httptest.NewRequest(http.MethodPost, "/echo", body)
	r.ServeHTTP(w, req)
	fmt.Printf("status=%d body=%s\n", w.Code, w.Body.String())
}

package main

import (
	"fmt"
	"io"
	"net"
	"net/http"
	"net/http/httptest"
	"time"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()
	r.GET("/slow", func(c *gin.Context) {
		time.Sleep(200 * time.Millisecond)
		c.String(http.StatusOK, "done")
	})

	// 不要用 r.Run()，自己建 Server 才能设超时
	srv := &http.Server{
		Handler:           r,
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       15 * time.Second,
		WriteTimeout:      30 * time.Second,
		IdleTimeout:       60 * time.Second,
	}

	// 用 httptest 驱动请求，不用真的占端口
	w := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodGet, "/slow", nil)
	start := time.Now()
	srv.Handler.ServeHTTP(w, req)
	fmt.Printf("status=%d 耗时=%v\n", w.Code, time.Since(start).Round(time.Millisecond))

	// 真实监听用的是同一个 srv，跑完立刻关掉
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		panic(err)
	}
	go srv.Serve(ln)
	resp, err := http.Get("http://" + ln.Addr().String() + "/slow")
	if err != nil {
		panic(err)
	}
	body, _ := io.ReadAll(resp.Body)
	resp.Body.Close()
	fmt.Printf("真实服务 status=%d body=%s\n", resp.StatusCode, body)
	srv.Close()
}

package main

import (
	"context"
	"fmt"
	"net"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()
	r.GET("/work", func(c *gin.Context) {
		time.Sleep(100 * time.Millisecond)
		c.String(http.StatusOK, "ok")
	})

	srv := &http.Server{Handler: r, ReadHeaderTimeout: 5 * time.Second}
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		panic(err)
	}

	// 第一步：监听信号
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()
	go func() {
		<-ctx.Done()
		// 第二步：停止收新连接，等存量请求做完，最多等 5 秒
		shutdownCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		if err := srv.Shutdown(shutdownCtx); err != nil {
			fmt.Println("优雅关闭超时:", err)
			os.Exit(1)
		}
		fmt.Println("已优雅关闭，存量请求处理完毕")
	}()

	go srv.Serve(ln)

	// 模拟 K8s 发来的 SIGTERM
	p, err := os.FindProcess(os.Getpid())
	if err != nil {
		panic(err)
	}
	p.Signal(syscall.SIGTERM)

	// 第三步：等关闭完成后进程自然退出
	time.Sleep(500 * time.Millisecond)
	fmt.Println("main 结束")
}

