import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"sync"
	"time"

	"github.com/gin-gonic/gin"
)

// bench 用固定并发打同一个 handler，返回每秒请求数
func bench(name string, h http.Handler, concurrency, total int) float64 {
	srv := httptest.NewServer(h)
	defer srv.Close()

	client := &http.Client{Transport: &http.Transport{
		MaxIdleConns:        concurrency,
		MaxIdleConnsPerHost: concurrency,
	}}
	jobs := make(chan struct{}, total)
	var wg sync.WaitGroup
	start := time.Now()
	for i := 0; i < concurrency; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for range jobs {
				resp, err := client.Get(srv.URL + "/api/ping")
				if err != nil {
					continue
				}
				io.Copy(io.Discard, resp.Body)
				resp.Body.Close()
			}
		}()
	}
	for i := 0; i < total; i++ {
		jobs <- struct{}{}
	}
	close(jobs)
	wg.Wait()

	elapsed := time.Since(start)
	qps := float64(total) / elapsed.Seconds()
	fmt.Printf("%-10s %d 次请求 / %v = %.0f req/s\n", name, total, elapsed.Round(time.Millisecond), qps)
	return qps
}

func main() {
	gin.SetMode(gin.ReleaseMode)

	// 两个 handler 做完全一样的活：把一个 map 编成 JSON 返回
	g := gin.New()
	g.GET("/api/ping", func(c *gin.Context) { c.JSON(http.StatusOK, gin.H{"message": "pong"}) })

	mux := http.NewServeMux()
	mux.HandleFunc("/api/ping", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json; charset=utf-8")
		json.NewEncoder(w).Encode(map[string]string{"message": "pong"})
	})

	const concurrency = 50
	const total = 50000
	bench("预热 gin", g, concurrency, 2000) // 预热，避开首次分配的干扰
	bench("预热 http", mux, concurrency, 2000)

	gqps := bench("gin", g, concurrency, total)
	nqps := bench("net/http", mux, concurrency, total)
	fmt.Printf("gin 是 net/http 的 %.2f 倍（同一台机器、同样 handler 逻辑，差距通常很小）\n", gqps/nqps)
}

