import (
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"sort"
	"sync"
	"time"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()
	r.GET("/api/ping", func(c *gin.Context) { c.JSON(http.StatusOK, gin.H{"message": "pong"}) })

	srv := httptest.NewServer(r)
	defer srv.Close()

	const concurrency = 20
	const total = 2000
	client := &http.Client{Transport: &http.Transport{
		MaxIdleConns:        concurrency,
		MaxIdleConnsPerHost: concurrency,
	}}

	latencies := make([]time.Duration, 0, total)
	var mu sync.Mutex
	var wg sync.WaitGroup
	start := time.Now()
	for i := 0; i < concurrency; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			local := make([]time.Duration, 0, total/concurrency)
			for j := 0; j < total/concurrency; j++ {
				t0 := time.Now()
				resp, err := client.Get(srv.URL + "/api/ping")
				if err != nil {
					continue
				}
				io.Copy(io.Discard, resp.Body)
				resp.Body.Close()
				local = append(local, time.Since(t0))
			}
			mu.Lock()
			latencies = append(latencies, local...)
			mu.Unlock()
		}()
	}
	wg.Wait()
	elapsed := time.Since(start)

	sort.Slice(latencies, func(i, j int) bool { return latencies[i] < latencies[j] })
	p := func(q float64) time.Duration {
		idx := int(float64(len(latencies))*q) - 1
		if idx < 0 {
			idx = 0
		}
		return latencies[idx]
	}
	fmt.Printf("%d 次请求 / %v = %.0f req/s\n", len(latencies), elapsed.Round(time.Millisecond), float64(len(latencies))/elapsed.Seconds())
	fmt.Printf("P50=%v P90=%v P99=%v Max=%v\n", p(0.50), p(0.90), p(0.99), latencies[len(latencies)-1])
}

