import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.ReleaseMode)

	// 准备静态目录和模板目录
	dir, err := os.MkdirTemp("", "gin-static")
	if err != nil {
		panic(err)
	}
	defer os.RemoveAll(dir)
	staticDir := filepath.Join(dir, "static")
	tplDir := filepath.Join(dir, "templates")
	os.MkdirAll(staticDir, 0o755)
	os.MkdirAll(tplDir, 0o755)
	os.WriteFile(filepath.Join(staticDir, "app.css"), []byte("body{color:red}"), 0o644)
	os.WriteFile(filepath.Join(tplDir, "index.tmpl"), []byte(`<h1>你好，{{.name}}</h1>`), 0o644)

	r := gin.New()
	// 第二个参数 false：不列目录内容
	r.StaticFS("/static", gin.Dir(staticDir, false))
	// 启动时一次性解析模板
	r.LoadHTMLGlob(filepath.Join(tplDir, "*.tmpl"))
	r.GET("/page", func(c *gin.Context) {
		c.HTML(http.StatusOK, "index.tmpl", gin.H{"name": "Gin"})
	})

	for _, path := range []string{"/static/app.css", "/page"} {
		w := httptest.NewRecorder()
		req := httptest.NewRequest(http.MethodGet, path, nil)
		r.ServeHTTP(w, req)
		fmt.Printf("%-16s -> %d %s\n", path, w.Code, w.Body.String())
	}
}

package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"sync"
	"time"

	"github.com/gin-gonic/gin"
)

// 包级 WaitGroup：让 main 等所有异步 goroutine 打完日志再退出
var wg sync.WaitGroup

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()
	r.Use(func(c *gin.Context) {
		c.Set("user_id", c.Param("id"))
		c.Next()
	})
	r.GET("/order/:id", func(c *gin.Context) {
		id := c.Param("id") // 先取成普通变量，再进 goroutine

		// 正确做法一：只传普通变量
		done := make(chan string, 1)
		go func(v string) { done <- "处理订单 " + v }(id)
		fmt.Println(<-done)

		// 正确做法二：需要 Context 就用 Copy()，且不能在里面写响应
		cp := c.Copy()
		wg.Add(1)
		go func(ctx *gin.Context, id string) {
			defer wg.Done()
			v, _ := ctx.Get("user_id")
			fmt.Printf("请求 %s：Copy 里读到的 user_id = %v\n", id, v)
		}(cp, id)

		// 反例：把原 Context 交给 goroutine，它活过了本次请求
		raw := c
		wg.Add(1)
		go func(id string) {
			defer wg.Done()
			time.Sleep(30 * time.Millisecond)
			v, _ := raw.Get("user_id")
			// 请求已结束，Context 被回收复用，这里可能读到下一个请求的值
			fmt.Printf("请求 %s：原 Context 在 goroutine 里读到的 user_id = %v\n", id, v)
		}(id)

		c.String(http.StatusOK, "ok")
	})

	for _, id := range []string{"1", "2"} {
		w := httptest.NewRecorder()
		req := httptest.NewRequest(http.MethodGet, "/order/"+id, nil)
		r.ServeHTTP(w, req)
	}
	wg.Wait()
}

