import (
	"database/sql"
	"database/sql/driver"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"sync"
	"time"

	"github.com/gin-gonic/gin"
)

// 假驱动：只为演示连接池参数，不真的连数据库
type stubDriver struct{}

func (stubDriver) Open(string) (driver.Conn, error) { return &stubConn{}, nil }

type stubConn struct{}

func (c *stubConn) Prepare(string) (driver.Stmt, error) { return &stubStmt{}, nil }
func (c *stubConn) Close() error                        { return nil }
func (c *stubConn) Begin() (driver.Tx, error)           { return stubTx{}, nil }

type stubTx struct{}

func (stubTx) Commit() error   { return nil }
func (stubTx) Rollback() error { return nil }

type stubStmt struct{}

func (s *stubStmt) Close() error  { return nil }
func (s *stubStmt) NumInput() int { return 0 }
func (s *stubStmt) Exec([]driver.Value) (driver.Result, error) {
	return driver.RowsAffected(0), nil
}
func (s *stubStmt) Query([]driver.Value) (driver.Rows, error) { return &stubRows{}, nil }

type stubRows struct{ done bool }

func (r *stubRows) Columns() []string { return []string{"id"} }
func (r *stubRows) Close() error      { return nil }
func (r *stubRows) Next(dest []driver.Value) error {
	if r.done {
		return io.EOF
	}
	r.done = true
	dest[0] = int64(7)
	return nil
}

func init() {
	sql.Register("stub", stubDriver{})
}

func main() {
	gin.SetMode(gin.ReleaseMode)

	db, err := sql.Open("stub", "")
	if err != nil {
		panic(err)
	}
	defer db.Close()
	db.SetMaxOpenConns(10)           // 最多同时打开 10 条连接
	db.SetMaxIdleConns(10)           // 空闲连接全部留着复用
	db.SetConnMaxLifetime(time.Hour) // 连接最长活 1 小时
	db.SetConnMaxIdleTime(10 * time.Minute)

	r := gin.New()
	r.GET("/db", func(c *gin.Context) {
		// 取一条连接占住 50 毫秒，模拟慢查询
		conn, err := db.Conn(c.Request.Context())
		if err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
			return
		}
		defer conn.Close()
		time.Sleep(50 * time.Millisecond)
		s := db.Stats()
		c.JSON(http.StatusOK, gin.H{"open": s.OpenConnections, "in_use": s.InUse, "idle": s.Idle})
	})

	// 并发 30 个请求，但池上限只有 10
	var wg sync.WaitGroup
	for i := 0; i < 30; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			w := httptest.NewRecorder()
			req := httptest.NewRequest(http.MethodGet, "/db", nil)
			r.ServeHTTP(w, req)
		}()
	}
	wg.Wait()

	s := db.Stats()
	fmt.Printf("池上限=10 实际打开=%d 空闲=%d 等待次数=%d 等待总时长=%v\n",
		s.OpenConnections, s.Idle, s.WaitCount, s.WaitDuration.Round(time.Millisecond))
}

package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"time"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()

	// 全局中间件：每条路由都会经过，包括健康检查和静态文件
	r.Use(func(c *gin.Context) {
		fmt.Println("  [全局] 前")
		start := time.Now()
		c.Next()
		fmt.Printf("  [全局] 后 耗时=%v\n", time.Since(start).Round(time.Millisecond))
	})

	// 路由组中间件：只有组内路由经过
	api := r.Group("/api")
	api.Use(func(c *gin.Context) {
		fmt.Println("  [组] 前")
		c.Next()
		fmt.Println("  [组] 后")
	})
	api.GET("/ping", func(c *gin.Context) { c.String(http.StatusOK, "pong") })
	r.GET("/health", func(c *gin.Context) { c.String(http.StatusOK, "ok") })

	for _, path := range []string{"/api/ping", "/health"} {
		fmt.Println("=== 请求", path, "===")
		w := httptest.NewRecorder()
		req := httptest.NewRequest(http.MethodGet, path, nil)
		r.ServeHTTP(w, req)
		fmt.Println("  响应:", w.Code, w.Body.String())
	}
}

package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

// hello 是待测 handler，抽成具名函数才能用一个 Context 直接调用
func hello(c *gin.Context) {
	c.String(http.StatusOK, "user="+c.GetString("user")+" name="+c.Param("name"))
}

func main() {
	gin.SetMode(gin.TestMode)

	// 一、整条路由：连中间件一起测
	r := gin.New()
	r.Use(func(c *gin.Context) {
		c.Set("user", "alice")
		c.Next()
	})
	r.GET("/hello/:name", hello)

	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest(http.MethodGet, "/hello/bob", nil))
	fmt.Println("路由:", w.Code, w.Body.String())

	// 二、单个 handler：不注册路由，直接造 Context
	w2 := httptest.NewRecorder()
	c, _ := gin.CreateTestContext(w2)
	c.Request = httptest.NewRequest(http.MethodGet, "/hello/bob", nil)
	c.Params = gin.Params{{Key: "name", Value: "bob"}}
	c.Set("user", "alice")
	hello(c)
	fmt.Println("handler:", w2.Code, w2.Body.String())
}
